create table avaliacoes (nota integer not null check ((nota<=5) and (nota>=1)), atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, produto_id bigint not null, usuario_id bigint not null, comentario varchar(500), atualizado_por varchar(255), criado_por varchar(255), primary key (id), unique (usuario_id, produto_id));
create table categorias (atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, atualizado_por varchar(255), criado_por varchar(255), descricao varchar(255), nome varchar(255) not null unique, primary key (id));
create table itens_pedido (preco_unitario numeric(10,2) not null, quantidade integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, pedido_id bigint not null, produto_id bigint not null, atualizado_por varchar(255), criado_por varchar(255), primary key (id));
create table pagamentos (valor numeric(10,2), atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, pago_em timestamp(6), pedido_id bigint not null unique, atualizado_por varchar(255), criado_por varchar(255), metodo varchar(255) check (metodo in ('PIX','BOLETO','CARTAO_CREDITO','CARTAO_DEBITO')), mp_payment_id varchar(255), mp_preference_id varchar(255), status varchar(255) not null check (status in ('PENDENTE','APROVADO','RECUSADO','CANCELADO','REEMBOLSADO')), primary key (id));
create table passe_eventos (dia date not null, id bigint generated by default as identity, usuario_id bigint not null, referencia varchar(100) not null, acao varchar(255) not null check (acao in ('CHECKIN','VIEW_PRODUCT','ADD_TO_CART','PURCHASE_APPROVED','SPEND_APPROVED_CENTS','REVIEW_SUBMITTED')), primary key (id), unique (usuario_id, dia, acao, referencia));
create table passe_missoes_progresso (concluida boolean not null, progresso_atual integer not null, recompensa_entregue boolean not null, atualizado_em timestamp(6), concluida_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, periodo_fim timestamp(6) not null, periodo_inicio timestamp(6) not null, recompensa_entregue_em timestamp(6), template_id bigint not null, temporada_id bigint not null, usuario_id bigint not null, atualizado_por varchar(255), criado_por varchar(255), primary key (id), unique (usuario_id, template_id, periodo_inicio));
create table passe_missoes_template (ativa boolean not null, meta_valor integer not null, ordem_exibicao integer not null, xp_recompensa integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, temporada_id bigint not null, periodicidade varchar(20) not null check (periodicidade in ('DIARIA','SEMANAL','MENSAL')), acao_tipo varchar(40) not null check (acao_tipo in ('CHECKIN','VIEW_PRODUCT','ADD_TO_CART','PURCHASE_APPROVED','SPEND_APPROVED_CENTS','REVIEW_SUBMITTED')), codigo varchar(80) not null, titulo varchar(120) not null, atualizado_por varchar(255), criado_por varchar(255), descricao varchar(255) not null, primary key (id), unique (temporada_id, codigo));
create table passe_progresso_usuarios (nivel_atual integer not null, xp_total integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, temporada_id bigint not null, ultimo_ganho_xp_em timestamp(6), usuario_id bigint not null, atualizado_por varchar(255), criado_por varchar(255), primary key (id), unique (usuario_id, temporada_id));
create table passe_recompensa_resgates (atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, pedido_utilizado_id bigint, recompensa_id bigint not null, temporada_id bigint not null, usuario_id bigint not null, codigo_entrega varchar(60) unique, atualizado_por varchar(255), criado_por varchar(255), primary key (id), unique (usuario_id, recompensa_id));
create table passe_recompensas_nivel (nivel integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, temporada_id bigint not null, tipo_digital varchar(60) not null, titulo varchar(120) not null, codigo varchar(160) not null, atualizado_por varchar(255), criado_por varchar(255), descricao varchar(255) not null, primary key (id), unique (temporada_id, nivel));
create table passe_temporadas (ano integer not null, ativa boolean not null, fim_em date not null, inicio_em date not null, mes integer not null, total_niveis integer not null, xp_por_nivel integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, nome varchar(120) not null, slug varchar(120) not null unique, atualizado_por varchar(255), criado_por varchar(255), primary key (id));
create table passe_xp_historico (estornado boolean default false not null, xp_ganho integer not null, atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, temporada_id bigint not null, usuario_id bigint not null, origem_tipo varchar(20) not null check (origem_tipo in ('MISSION','PURCHASE')), referencia varchar(160) not null, atualizado_por varchar(255), criado_por varchar(255), descricao varchar(255) not null, primary key (id), unique (usuario_id, temporada_id, origem_tipo, referencia));
create table pedidos (desconto numeric(10,2) not null, frete numeric(10,2) not null, subtotal numeric(10,2) not null, total numeric(10,2) not null, atualizado_em timestamp(6), criado_em timestamp(6), data_pedido timestamp(6) not null, id bigint generated by default as identity, temporada_passe_id bigint, usuario_id bigint not null, numero varchar(30) not null unique, checkout_key varchar(100) unique, atualizado_por varchar(255), cep_entrega varchar(255), cidade_entrega varchar(255), complemento_entrega varchar(255), criado_por varchar(255), endereco_entrega varchar(255), estado_entrega varchar(255), nome_destinatario varchar(255), observacoes varchar(255), status varchar(255) check (status in ('PENDENTE','CONFIRMADO','ENVIADO','ENTREGUE','CANCELADO')), telefone_contato varchar(255), primary key (id));
create table produtos (ativo boolean not null, destaque boolean not null, estoque integer not null check (estoque>=0), preco numeric(10,2) not null, atualizado_em timestamp(6), categoria_id bigint, criado_em timestamp(6), id bigint generated by default as identity, sku varchar(40) unique, marca varchar(80), descricao_curta varchar(180), atualizado_por varchar(255), criado_por varchar(255), descricao TEXT, imagem_url varchar(255), nome varchar(255) not null, primary key (id));
create table usuarios (atualizado_em timestamp(6), criado_em timestamp(6), id bigint generated by default as identity, nome varchar(100) not null, atualizado_por varchar(255), criado_por varchar(255), email varchar(255) not null unique, role varchar(255) not null check (role in ('ADMIN','CLIENTE')), senha varchar(255) not null, tema_passe varchar(255), primary key (id));
